\chapter*{List of Symbols}
\addcontentsline{toc}{chapter}{List of Symbols}
\begin{description}
\item[$C$] condition code assigned to a bridge component
\item[$T$] torque applied to a bolt during a hardware check
\item[$n$] number of flagged components in a district
\end{description}
